def sizedCombinationSum(candidates, k, target):
    cands = sorted(candidates)
    top = cands[-1]
    res = []
    cur = []

    def go(start, m, left):
        if m == 0:
            if left == 0:
                res.append(cur[:])
            return
        if top * m < left:
            return
        for i in range(start, len(cands)):
            c = cands[i]
            if c * m > left:
                break
            cur.append(c)
            go(i, m - 1, left - c)
            cur.pop()

    go(0, k, target)
    return res
